// watCaseTables builds the two simple-case span tables as WAT globals
// from the running toolchain's unicode tables. A constant frozen at
// generation time drifted across Go/Unicode versions (CI span-count
// mismatch); generating per toolchain keeps compiled upper/lower
// byte-identical with the interpreter built from the same Go — the parity
// that matters (DESIGN-M2 §1 amendment, 2026-11-15).
func watCaseTables() string {
	var b strings.Builder
	b.WriteString("\n")
	watWriteCaseTable(&b, "$zhex_case_upper", unicode.UpperCase)
	b.WriteString("\n")
	watWriteCaseTable(&b, "$zhex_case_lower", unicode.LowerCase)
	b.WriteString("\n")
	return b.String()
}

// watWriteCaseTable emits one (lo, hi, delta) span table as a WAT global.
// The walk mirrors what unicode.ToUpper/ToLower compute per rune: plain
// CaseRange entries apply their constant delta, UpperLower entries
// alternate upper/lower pairs at distance 1 (even offset from Lo is
// uppercase), and adjacent equal-delta spans merge.
func watWriteCaseTable(b *strings.Builder, name string, dir int) {
	type caseSpan struct{ lo, hi, delta int32 }
	var spans []caseSpan
	add := func(lo, hi, delta rune) {
		if delta == 0 {
			return
		}
		if n := len(spans); n > 0 && spans[n-1].hi+1 == int32(lo) && spans[n-1].delta == int32(delta) {
			spans[n-1].hi = int32(hi)
			return
		}
		spans = append(spans, caseSpan{int32(lo), int32(hi), int32(delta)})
	}
	for i := range unicode.CaseRanges {
		cr := &unicode.CaseRanges[i]
		lo, hi, d := rune(cr.Lo), rune(cr.Hi), cr.Delta
		if d[unicode.UpperCase] == unicode.UpperLower || d[unicode.LowerCase] == unicode.UpperLower {
			if dir == unicode.UpperCase {
				for r := lo + 1; r <= hi; r += 2 {
					add(r, r, -1)
				}
			} else {
				for r := lo; r <= hi; r += 2 {
					add(r, r, 1)
				}
			}
			continue
		}
		add(lo, hi, d[dir])
	}
	fmt.Fprintf(b, "(global %s (ref $zhex_arr_i32)\n  (array.new_fixed $zhex_arr_i32 %d\n", name, len(spans)*3)
	for i, s := range spans {
		end := ""
		if i == len(spans)-1 {
			end = "))"
		}
		fmt.Fprintf(b, "    (i32.const %d) (i32.const %d) (i32.const %d)%s\n", s.lo, s.hi, s.delta, end)
	}
}

